package com.bank.dispatch;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class DispatchDemo {
    private static final Logger log = Logger.getLogger("Dispatch");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        GeoIndex geo = new GeoIndex();
        geo.update("VAN-1", 12.9716, 77.5946, true);  // free
        geo.update("VAN-2", 12.9760, 77.6000, true);  // free, farther
        geo.update("VAN-3", 12.9718, 77.5950, false); // busy

        MatchingService matcher = new MatchingService(geo);
        PricingService pricing = new PricingService();
        TripStateMachine fsm = new TripStateMachine();

        // Rajesh requests a cash delivery at his branch location
        double riderLat = 12.9717, riderLon = 77.5948;
        Trip trip = new Trip("TRIP-1", "SAV2001");
        log.info(() -> "Trip state: " + trip.getState());

        String van = matcher.matchNearest(riderLat, riderLon, 3.0);
        if (van == null) { log.severe("No van available"); return; }
        log.info(() -> "Matched " + van);
        fsm.transition(trip, Trip.State.MATCHED);

        // Surge: 5 open requests, 2 free vans → ratio 2.5 → capped
        BigDecimal baseFare = new BigDecimal("200");
        BigDecimal mult = pricing.surgeMultiplier(5, 2);
        BigDecimal fare = baseFare.multiply(mult);
        log.info(() -> "Surge x" + mult + " fare Rs." + fare);

        fsm.transition(trip, Trip.State.DRIVER_ARRIVED);
        fsm.transition(trip, Trip.State.IN_PROGRESS);
        fsm.transition(trip, Trip.State.COMPLETED);
        log.info(() -> "Final trip state: " + trip.getState());
    }
}

