// ─── File: GeoIndex.java ───
package com.bank.dispatch;

import java.util.*;

public class GeoIndex {
    static class Loc { double lat, lon; boolean free;
        Loc(double a, double o, boolean f){lat=a;lon=o;free=f;} }
    private final Map<String, Loc> drivers = new HashMap<>();

    public void update(String id, double lat, double lon, boolean free) {
        drivers.put(id, new Loc(lat, lon, free));
    }
    public void setFree(String id, boolean free) { drivers.get(id).free = free; }
    public boolean isFree(String id) { return drivers.get(id).free; }

    // Haversine distance in km (production uses a geohash/Redis GEO query)
    public double distanceKm(double lat1, double lon1, double lat2, double lon2) {
        double R = 6371.0;
        double dLat = Math.toRadians(lat2 - lat1), dLon = Math.toRadians(lon2 - lon1);
        double a = Math.sin(dLat/2)*Math.sin(dLat/2)
                 + Math.cos(Math.toRadians(lat1))*Math.cos(Math.toRadians(lat2))
                 * Math.sin(dLon/2)*Math.sin(dLon/2);
        return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    }

    public List<Map.Entry<String,Double>> nearby(double lat, double lon, double radiusKm) {
        List<Map.Entry<String,Double>> out = new ArrayList<>();
        for (var e : drivers.entrySet()) {
            if (!e.getValue().free) continue;
            double d = distanceKm(lat, lon, e.getValue().lat, e.getValue().lon);
            if (d <= radiusKm) out.add(Map.entry(e.getKey(), d));
        }
        out.sort(Map.Entry.comparingByValue());
        return out;
    }
}
