// ─── File: MatchingService.java ───
package com.bank.dispatch;

import java.util.*;
import java.util.logging.*;

public class MatchingService {
    private static final Logger log = Logger.getLogger("Dispatch");
    private final GeoIndex geo;
    public MatchingService(GeoIndex geo) { this.geo = geo; }

    // find nearest FREE van and atomically CLAIM it so no double-dispatch
    public synchronized String matchNearest(double lat, double lon, double radiusKm) {
        for (var cand : geo.nearby(lat, lon, radiusKm)) {
            String id = cand.getKey();
            if (geo.isFree(id)) {
                geo.setFree(id, false);      // atomic claim
                log.info(() -> "Claimed " + id + " at " + String.format("%.2f", cand.getValue()) + " km");
                return id;
            }
        }
        return null;
    }
}
