package com.bank.dispatch;

import java.math.BigDecimal;

public class PricingService {
    public BigDecimal surgeMultiplier(int openRequests, int availableDrivers) {
        if (availableDrivers == 0) return new BigDecimal("3.0");
        double ratio = (double) openRequests / availableDrivers;
        if (ratio <= 1.0) return BigDecimal.ONE;
        double m = Math.min(3.0, 1.0 + (ratio - 1.0));
        return BigDecimal.valueOf(m).setScale(1, java.math.RoundingMode.HALF_UP);
    }
}
