package com.bank.dispatch;

public class Trip {
    public enum State { REQUESTED, MATCHED, DRIVER_ARRIVED, IN_PROGRESS, COMPLETED, CANCELLED }
    private final String tripId;
    private final String riderId;
    private State state = State.REQUESTED;

    public Trip(String tripId, String riderId) { this.tripId = tripId; this.riderId = riderId; }
    public String getTripId() { return tripId; }
    public State getState() { return state; }
    void setState(State s) { this.state = s; }
}
