// ─── File: TripStateMachine.java ───
package com.bank.dispatch;

import java.util.*;
import java.util.logging.*;

public class TripStateMachine {
    private static final Logger log = Logger.getLogger("Dispatch");
    private static final Map<Trip.State, Set<Trip.State>> LEGAL = Map.of(
        Trip.State.REQUESTED,      Set.of(Trip.State.MATCHED, Trip.State.CANCELLED),
        Trip.State.MATCHED,        Set.of(Trip.State.DRIVER_ARRIVED, Trip.State.CANCELLED),
        Trip.State.DRIVER_ARRIVED, Set.of(Trip.State.IN_PROGRESS, Trip.State.CANCELLED),
        Trip.State.IN_PROGRESS,    Set.of(Trip.State.COMPLETED),
        Trip.State.COMPLETED,      Set.of(),
        Trip.State.CANCELLED,      Set.of());

    public void transition(Trip trip, Trip.State to) {
        Trip.State from = trip.getState();
        if (!LEGAL.getOrDefault(from, Set.of()).contains(to))
            throw new IllegalStateException("Illegal transition " + from + " -> " + to);
        trip.setState(to);
        log.info(() -> "Trip " + trip.getTripId() + ": " + from + " -> " + to);
    }
}
